"""Inspect the workspace: list files and report SQLite database schemas."""

import os
import sqlite3

base = os.path.dirname(os.path.abspath(__file__))
print("Script directory:", base)
print("Working directory:", os.getcwd())

for root in (base, os.getcwd()):
    print("\n--- Listing:", root, "---")
    try:
        for entry in sorted(os.listdir(root)):
            print(entry)
    except OSError as exc:
        print("Could not list:", exc)

# Inspect every .db file found in either location.
dbs = set()
for root in (base, os.getcwd()):
    try:
        for entry in sorted(os.listdir(root)):
            if entry.lower().endswith(".db"):
                dbs.add(os.path.join(root, entry))
    except OSError:
        pass

for db_path in sorted(dbs):
    print("\n=== Database:", db_path, "===")
    try:
        with sqlite3.connect(db_path) as conn:
            cur = conn.cursor()
            tables = cur.execute(
                "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
            ).fetchall()
            print("Tables:", [t[0] for t in tables])
            for (name,) in tables:
                cols = cur.execute('PRAGMA table_info("%s")' % name).fetchall()
                print("  %s:" % name, [(c[1], c[2]) for c in cols])
    except sqlite3.Error as exc:
        print("Error reading db:", exc)

"""Inspect the workspace: list files and describe any SQLite databases.

Task-local helper for the login-script request: we need to know the name
and schema of the .db file before writing the registration script.

This helper is read-only: it never writes to or modifies any database.
"""

import hashlib
import os
import sqlite3
import sys


def describe_db(path: str) -> None:
    """Print file metadata and the SQLite schema for one database file."""
    print(f"\n=== {path} ===")
    print(f"size: {os.path.getsize(path)} bytes")
    with open(path, "rb") as fh:
        digest = hashlib.sha256(fh.read()).hexdigest()
    print(f"sha256: {digest}")

    try:
        conn = sqlite3.connect(path)
    except sqlite3.Error as exc:
        print(f"  not a readable SQLite database: {exc}")
        return

    with conn:
        cur = conn.cursor()
        cur.execute(
            "SELECT type, name, sql FROM sqlite_master ORDER BY type, name"
        )
        rows = cur.fetchall()
        if not rows:
            print("  (no objects in this database)")
        for typ, name, sql in rows:
            print(f"  {typ}: {name}")
            if sql:
                print(f"    sql: {sql}")

        for typ, name, _sql in rows:
            if typ != "table":
                continue
            # Row counts / column names only -- no row data is printed.
            try:
                cur.execute(f'SELECT COUNT(*) FROM "{name}"')
                count = cur.fetchone()[0]
            except sqlite3.Error as exc:
                count = f"<error: {exc}>"
            print(f"  table {name}: {count} rows")
            try:
                cur.execute(f'PRAGMA table_info("{name}")')
                cols = cur.fetchall()
                print(
                    "    columns: "
                    + ", ".join(f"{c[1]} {c[2]}" for c in cols)
                )
            except sqlite3.Error as exc:
                print(f"    columns: <error: {exc}>")
    conn.close()


def main() -> int:
    print("cwd:", os.getcwd())
    print("argv:", sys.argv[1:])
    print("workspace entries:")
    for entry in sorted(os.listdir(".")):
        print(" -", entry)

    db_suffixes = (".db", ".sqlite", ".sqlite3", ".db3")
    dbs = [
        f
        for f in sorted(os.listdir("."))
        if f.lower().endswith(db_suffixes) and os.path.isfile(f)
    ]
    if not dbs:
        print("\nNo .db files found in the workspace.")
        return 0
    for db in dbs:
        describe_db(db)
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Inspect the workspace for SQLite databases and report their schemas.

This helper is used only to discover the shape of the local database(s)
so the login/registration script can be written against the real schema.
Databases are opened read-only; nothing is ever modified here.
"""

from __future__ import annotations

import sqlite3
from pathlib import Path


def find_databases(root: Path) -> list[Path]:
    """Return all *.db files under root, skipping common tooling dirs."""
    found: list[Path] = []
    skip_dirs = {".venv", "venv", "__pycache__", ".git", "node_modules"}
    for path in root.rglob("*.db"):
        if any(part in skip_dirs for part in path.parts):
            continue
        found.append(path)
    return sorted(found)


def inspect_database(db_path: Path) -> None:
    """Print schema and row counts for one SQLite database (read-only)."""
    print(f"\n=== {db_path} ({db_path.stat().st_size} bytes) ===")
    uri = f"file:{db_path.resolve()}?mode=ro"
    try:
        with sqlite3.connect(uri, uri=True) as conn:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()

            cur.execute("SELECT name, type, sql FROM sqlite_master ORDER BY type, name")
            rows = cur.fetchall()
            if not rows:
                print("  (no objects in sqlite_master)")
            for row in rows:
                print(f"  [{row['type']}] {row['name']}")
                if row["sql"]:
                    print(f"      SQL: {row['sql']}")

            cur.execute("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")
            tables = cur.fetchall()
            for table in tables:
                table_name = table["name"]
                print(f"  table {table_name} columns:")
                cur.execute(f'PRAGMA table_info("{table_name}")')
                for col in cur.fetchall():
                    print(
                        f"      {col['name']} {col['type']} "
                        f"notnull={col['notnull']} default={col['dflt_value']!r} pk={col['pk']}"
                    )
                try:
                    cur.execute(f'SELECT COUNT(*) AS n FROM "{table_name}"')
                    print(f"      row_count={cur.fetchone()['n']}")
                except sqlite3.Error as exc:
                    print(f"      (cannot count: {exc})")
    except sqlite3.Error as exc:
        print(f"  ERROR opening as SQLite: {exc}")


def main() -> None:
    root = Path.cwd()
    dbs = find_databases(root)
    if not dbs:
        print(f"No .db files found under {root}")
        return
    for db in dbs:
        inspect_database(db)


if __name__ == "__main__":
    main()

